# Verify my rule
test_input = [[3, 0, 0], [3, 3, 3], [0, 0, 3]]
pattern_value = None
non_zero_cells = []

for r in range(3):
    for c in range(3):
        if test_input[r][c] != 0:
            non_zero_cells.append((r, c))
            if pattern_value is None:
                pattern_value = test_input[r][c]
            elif pattern_value != test_input[r][c]:
                print(f"Pattern cells have different values: {pattern_value} vs {test_input[r][c]}")

print(f"Pattern value: {pattern_value}")
print(f"Non-zero cells: {non_zero_cells}")
print(f"Number of non-zero cells: {len(non_zero_cells)}")

bg_value = pattern_value // 3  # floor division
print(f"Background value: {bg_value}")

# Compute output
test_output = [[0]*3 for _ in range(3)]
for r in range(3):
    for c in range(3):
        if test_input[r][c] == 0:
            test_output[r][c] = bg_value

print("Predicted output:")
for row in test_output:
    print(row)

# Display input/output side by side
print("\nInput → Output:")
for r in range(3):
    print(f"[{test_input[r]}] → [{test_output[r]}]")
